-- Members (REQUIREMENTS.md section 6). Ids are UUIDv7 generated by the
-- server. The e-mail address is stored already normalised (trimmed, lower
-- case) by the application and is unique among live members only: DELETE
-- /v1/me detaches it at once (email = NULL, deleted_at set) so the same
-- address can sign up again while the old member's data is being erased.

-- +goose Up
CREATE TABLE members (
    id                 uuid        PRIMARY KEY,
    email              text,
    display_name       text,
    country_code       text,
    region_code        text,
    ranking_opt_in     boolean     NOT NULL DEFAULT false,
    auth_provider      text        NOT NULL DEFAULT 'email_otp',
    -- Bumped on every profile change; the ETag for PATCH /v1/me.
    version            bigint      NOT NULL DEFAULT 1,
    -- Access JWTs issued before this instant are rejected (DELETE /v1/me,
    -- logout everywhere). NULL means no cut-off.
    tokens_valid_after timestamptz,
    created_at         timestamptz NOT NULL DEFAULT now(),
    updated_at         timestamptz NOT NULL DEFAULT now(),
    -- Set by DELETE /v1/me. The row (and, by cascade, everything the member
    -- owns) is erased later by a background job, within 30 days.
    deleted_at         timestamptz,

    CONSTRAINT members_live_has_email CHECK (deleted_at IS NOT NULL OR email IS NOT NULL),
    CONSTRAINT members_deleted_has_no_email CHECK (deleted_at IS NULL OR email IS NULL),
    CONSTRAINT members_email_length CHECK (length(email) <= 254),
    CONSTRAINT members_display_name_length CHECK (char_length(display_name) BETWEEN 1 AND 40),
    CONSTRAINT members_country_code_format CHECK (country_code ~ '^[A-Z]{2}$')
);

CREATE UNIQUE INDEX members_email_key ON members (email) WHERE email IS NOT NULL;
CREATE INDEX members_pending_erasure_idx ON members (deleted_at) WHERE deleted_at IS NOT NULL;

-- +goose Down
DROP TABLE members;
